#include "U8G2GLDisplay.hpp"

#include <Arduino.h>

// Generated by U8G2GL (library U8G2GLUI). It must come before any runtime header:
// it first includes the generated capacities, which only take effect if seen
// before u8g2gl_config.h (a macro defined twice is a redefinition warning).
#include "ui.hpp"

#include <u8g2gl/u8g2gl_core.h>  // u8g2gl_set_tick_cb()

bool U8G2GLDisplay::_begun = false;

namespace {

/**
 * @brief The runtime's time source: milliseconds since boot.
 *
 * u8g2gl_set_tick_cb() takes a plain function pointer returning uint32_t, and
 * Arduino's millis() returns unsigned long, so a one-line adapter is needed.
 * Registered for completeness: only the runtime's ui_handler() reads it, and
 * this module's boards never call that (ruling R1 of U8G2GL PR-05: the legacy
 * module owns the draw loop; the board passes the carousel's time to tick_fn
 * directly), but anything that does would otherwise see time stuck at 0.
 *
 * @return Milliseconds since boot.
 */
uint32_t tickNow() {
    return static_cast<uint32_t>(millis());
}

}  // namespace

/**
 * @brief Register the runtime's time source, then initialise the generated UI.
 */
void U8G2GLDisplay::begin() {
    // --- Guard: ui_init() must run exactly once ---
    if (_begun) {
        return;
    }
    _begun = true;

    // --- Step 1: Time source ---
    // Registered before ui_init() so the time source is in place before any
    // generated code runs; a caller of ui_handler() would otherwise see 0.
    u8g2gl_set_tick_cb(tickNow);

    // --- Step 2: Generated subjects, styles and screens ---
    ui_init();
}

/** @brief Returns true once begin() has run. */
bool U8G2GLDisplay::isReady() {
    return _begun;
}
